{"command": "cd /app && echo "import json
import os

def generate_schedule():
    with open('pending_orders.json', 'r') as f:
        orders = json.load(f)

    schedule = []
    for idx, order in enumerate(orders):
        # Simulate a basic flight path (example: starting from a central hub)
        flight_path = [
            (order['pickup_lat'], order['pickup_lon']),
            (order['delivery_lat'], order['delivery_lon'])
        ]
        schedule.append({
            'order_id': order['order_id'],
            'flight_path': flight_path,
            'drone_id': f'DRONE_{idx+1}'
        ])

    with open('output/schedule.json', 'w') as f:
        json.dump(schedule, f)

if __name__ == '__main__':
    generate_schedule()" > schedule_delivery_drones.py"}

